/**
 * Validates the [key] segment of /app/exercises/[key]: a URL-encoded exercise key
 * as generated by the database (lower(btrim(name)), 1–40 characters).
 */
export function parseExerciseKey(segment: string): string | null {
  let decoded: string;
  try {
    decoded = decodeURIComponent(segment);
  } catch {
    return null;
  }
  const key = decoded.trim().toLowerCase();
  if (key.length < 1 || key.length > 40 || key !== decoded) return null;
  return key;
}

export function exerciseHref(key: string): string {
  return `/app/exercises/${encodeURIComponent(key)}`;
}
